/// <summary>
/// XML Formatter class for general orders.
/// </summary>
class TFMXMLFormatOrders extends TFMXMLFormat
{
    str                     backendId;
    str                     status;
    str                     headerLabel1;
    str                     headerLabel2;
    str                     headerValue1;
    str                     headerValue2;

}

Method.Source:
    protected void setValues()
    {
		if (sdt && sdt.titleField1())
        {
            if (!headerLabel1)
            {
                headerLabel1            = new DictField(common.tableId, sdt.titleField1()).Label();
                headerValue1            = common.(sdt.titleField1());
            }
            if (!displayLine1)
            {
                fieldsToAdd.insert(TFMConstants::DisplayLine1()+ '_Label', headerLabel1);
                fieldsToAdd.insert(TFMConstants::DisplayLine1(), headerValue1);
            }

        }
        if (sdt && sdt.titleField2())
        {
            if (!headerLabel2)
            {
                headerLabel2            = new DictField(common.tableId, sdt.titleField2()).label();
                headerValue2            = common.(sdt.titleField2());
            }
			if (!displayLine2)
            {
                fieldsToAdd.insert(TFMConstants::DisplayLine2()+ '_Label', headerLabel2);
                fieldsToAdd.insert(TFMConstants::DisplayLine2(), headerValue2);
            }
        }
        super();



    }

public str parmHeaderValue1(str _headerValue1 = headerValue1)
{
    headerValue1 = _headerValue1;
    return headerValue1;
}

public str parmHeaderValue2(str _headerValue2 = headerValue2)
{
    headerValue2 = _headerValue2;
    return headerValue2;
}

public str parmHeaderLabel1(str _headerLabel1 = headerLabel1)
{
    headerLabel1 = _headerLabel1;
    return headerLabel1;
}

public str parmHeaderLabel2(str _headerLabel2 = headerLabel2)
{
    headerLabel2 = _headerLabel2;
    return headerLabel2;
}

    public void convertFieldsToMap()
    {        
  	if (!backendId)
        {
            backendId = TFMHelper::generateBackendId(common,orderType);
        }
        fieldsToAdd.insert(TFMConstants::BackendId(), fieldsToAdd.exists(TFMConstants::BackendId()) ? fieldsToAdd.lookup(TFMConstants::BackendId()) : backendId);
        //status
        if (!fieldsToAdd.exists(TFMConstants::Status()))
        {
            status =  TFMLockedOrders::isOrderLocked(backendid,deviceId, TFMlockingLevel::User) ? TFMConstants::locked() : TFMConstants::Unlocked();
            fieldsToAdd.insert(TFMConstants::Status(), fieldsToAdd.exists(TFMConstants::Status()) ? fieldsToAdd.lookup(TFMConstants::Status()) : status);
        }
        else
        {
            status = fieldsToAdd.lookup(TFMConstants::Status());
        }
        if(status == TFMConstants::locked())
        {
            displayLine5 += (displayLine5 ? "@TFM:lineBreak" : '') + strFmt("@TFM:Orderlockedby",HcmWorker::find(HcmWorker::userId2Worker(TFMLockedOrders::find(backendId,'').UserID)).name());
        }
        fieldsToAdd.insert('lockedImage', status == TFMConstants::locked() ? resourceStr(TFMLocked) : 'unlocked');
        fieldsToAdd.insert(TFMConstants::HeaderLabel1(), fieldsToAdd.exists(TFMConstants::HeaderLabel1()) ? fieldsToAdd.lookup(TFMConstants::HeaderLabel1()) : headerLabel1);
        fieldsToAdd.insert(TFMConstants::HeaderLabel2(), fieldsToAdd.exists(TFMConstants::HeaderLabel2()) ? fieldsToAdd.lookup(TFMConstants::HeaderLabel2()) : headerLabel2);
        fieldsToAdd.insert(TFMConstants::HeaderValue1(), fieldsToAdd.exists(TFMConstants::HeaderValue1()) ? fieldsToAdd.lookup(TFMConstants::HeaderValue1()) : headerValue1);
        fieldsToAdd.insert(TFMConstants::HeaderValue2(), fieldsToAdd.exists(TFMConstants::HeaderValue2()) ? fieldsToAdd.lookup(TFMConstants::HeaderValue2()) : headerValue2);

		if (ds.showImages)
        {
            if (!imageID)
			{
				imageID = strReplace(backendId,'/','|');
			}
			fieldsToAdd.insert('imageId', fieldsToAdd.exists('imageId') ? fieldsToAdd.lookup('imageId') : imageID);
        }
        super();
    }

public void appendToXML(XmlElement _parentNode)
{
    recordLineTag = TFMConstants::BaseOrder();
    super(_parentNode);
}
